{
  "pou_name": "fixture_motor_start_stop",
  "pou_type": "FUNCTION_BLOCK",
  "declaration": "FUNCTION_BLOCK 'fixture_motor_start_stop'
VAR_INPUT
    StartBtn : BOOL;
    StopBtn : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR
VAR
    motor_state : BOOL;
END_VAR
END_FUNCTION_BLOCK",
  "implementation": "IF StopBtn OR EStop THEN
    motor_state := FALSE;
ELSIF StartBtn THEN
    motor_state := TRUE;
END IF;
Motor := motor_state;"
}
